#include "l2_parser.h"

#include <stdint.h>
#include <string.h>

static const char header[]="schema,seq,monotonic_ms,quality,event,workspace,role,activity,l1_condition,provenance\n";
bool l2_parse_header(const char *line,size_t n){return line&&n==sizeof(header)-1U&&memcmp(line,header,n)==0;}
static bool decimal(const char *s,uint64_t maximum,uint64_t *out){if(!s||!*s)return false;const char *start=s;uint64_t v=0;for(;*s;s++){if(*s<'0'||*s>'9')return false;uint8_t d=(uint8_t)(*s-'0');if(d>maximum||v>(maximum-d)/10U)return false;v=v*10U+d;}if(start[0]=='0'&&start[1])return false;*out=v;return true;}
static int token(const char *s,const char *const *names,size_t count){for(size_t i=0;i<count;i++)if(strcmp(s,names[i])==0)return(int)i;return -1;}
bool l2_parse_event_line(const char *line,size_t n,L2Event *out){if(!line||!out||n==0||n>L2_MAX_LINE||line[n-1U]!='\n')return false;for(size_t i=0;i+1U<n;i++){unsigned char byte=(unsigned char)line[i];if(byte<0x20U||byte>0x7eU)return false;}char copy[L2_MAX_LINE+1U];memcpy(copy,line,n);copy[n-1U]='\0';if(strchr(copy,'\r')||strchr(copy,'"')||strchr(copy,' ')||strchr(copy,'\t'))return false;size_t commas=0;for(const char *scan=copy;*scan;scan++)if(*scan==',')commas++;if(commas!=9U)return false;char *field[10];size_t fields=0;char *p=copy;while(fields<10U){field[fields++]=p;char *comma=strchr(p,',');if(!comma)break;*comma='\0';p=comma+1;}if(fields!=10U)return false;if(strcmp(field[0],"HMI_L2_EVENT_V1")||strcmp(field[9],"SIMULATED"))return false;uint64_t seq,now,w;if(!decimal(field[1],UINT64_MAX,&seq)||!decimal(field[2],UINT64_MAX,&now)||!decimal(field[5],4,&w))return false;static const char *const qualities[]={"OK","ABSENT","INVALID","RESET"};static const char *const events[]={"SESSION_BEGIN","SESSION_END","ROLE","CONTEXT","QUERY","GAP","RESET"};static const char *const roles[]={"NONE","CODE_EDIT","BUILD_TEST","DOC_VIEW","REFERENCES","CANVAS","ASSET_GROUP","EXPORT","OTHER"};static const char *const activities[]={"NONE","IDLE","INTERACTIVE","BACKGROUND","MULTI_TASK","UNKNOWN"};static const char *const conditions[]={"NONE","QUIET","CPU_PRESSURE","MEMORY_PRESSURE","IO_PRESSURE","MIXED_PRESSURE","UNKNOWN","UNRELIABLE"};int q=token(field[3],qualities,4),k=token(field[4],events,7),r=token(field[6],roles,9),a=token(field[7],activities,6),c=token(field[8],conditions,8);if(q<0||k<0||r<0||a<0||c<0)return false;bool placement=false;if(k==L2_EVENT_SESSION_BEGIN||k==L2_EVENT_SESSION_END)placement=w>0&&r==L2_ROLE_NONE&&a==L2_ACTIVITY_NONE&&c==L2_CONDITION_NONE;else if(k==L2_EVENT_ROLE)placement=w>0&&r!=L2_ROLE_NONE&&a==L2_ACTIVITY_NONE&&c==L2_CONDITION_NONE;else if(k==L2_EVENT_CONTEXT)placement=r==L2_ROLE_NONE&&a!=L2_ACTIVITY_NONE&&c!=L2_CONDITION_NONE;else if(k==L2_EVENT_QUERY)placement=w>0&&r==L2_ROLE_NONE&&a==L2_ACTIVITY_NONE&&c==L2_CONDITION_NONE;else if(k==L2_EVENT_GAP||k==L2_EVENT_RESET)placement=w==0&&r==L2_ROLE_NONE&&a==L2_ACTIVITY_NONE&&c==L2_CONDITION_NONE;if(!placement||((q==L2_QUALITY_RESET)!=(k==L2_EVENT_RESET)))return false;*out=(L2Event){seq,now,(L2Quality)q,(L2EventKind)k,(uint8_t)w,(L2Role)r,(L2Activity)a,(L2Condition)c,true};return true;}
